package com.ashokmart.servlet;
import com.ashokmart.util.DatabaseConnectionPool; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/orders/view") public final class AdminOrderDetailsServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(AdminOrderDetailsServlet.class); public void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{var admin=AdminWebSupport.authenticatedAdmin(req,res);if(admin==null)return;try{long id=Long.parseLong(req.getParameter("id"));if(id<=0)throw new NumberFormatException();var detail=AdminWebSupport.adminOrderService(AdminWebSupport.pool(getServletContext())).getOrder(admin.userId(),id);if(detail.isEmpty()){res.sendError(404,"Order not found.");return;}req.setAttribute("adminOrder",detail.get());req.getRequestDispatcher("/WEB-INF/views/admin-order-details.jsp").forward(req,res);}catch(NumberFormatException e){res.sendError(404,"Order not found.");}catch(IllegalStateException e){LOG.error("Admin order details failed",e);res.sendError(500,"Order details are temporarily unavailable.");}}}
